# Define a custom function
calculate_factorial <- function(n) {
  if (n <= 1) {
    return(1)
  } else {
    return(n * calculate_factorial(n - 1))
  }
}

# Use the function
result <- calculate_factorial(5)
cat("5! =", result, "\n")

# For loop example
for (i in 1:5) {
  cat("Iteration", i, ":", i^2, "\n")
}
